(p/'Exporter.cs').write_text('''using System;using System.Linq;using System.Collections.Generic;using System.Text.Json;using UnityEngine;using Emberfall;
class Exporter { static void Main() { var cases=new List<object>();for(int h=0;h<4;h++)for(int tier=-1;tier<2;tier++)for(int wing=0;wing<2;wing++) {var host=new GameObject("sample");var model=CombatModel.Hero(host.transform,(HeroClass)h); if(tier>=0)model.ApplyEquipment(new ItemData{id="w",slot=ItemSlot.Weapon,level=tier==0?1:100,rarity=Rarity.Legendary},new ItemData{id="a",slot=ItemSlot.Armor,level=tier==0?1:100,rarity=Rarity.Legendary},null); if(wing==1)model.ApplyFashion(new FashionData{id="wings",slot=FashionSlot.Wings,rarity=Rarity.Epic},null);UnityEngine.Object.Flush();var parts=model.GetComponentsInChildren<MeshFilter>(false).Where(x=>x.sharedMesh?.vertices!=null).Select(x=>new { name=x.transform.name,vertices=x.sharedMesh.vertices.Select(v=>{var w=x.transform.TransformPoint(v);return new[]{w.x,w.y,w.z};}).ToArray(),triangles=x.sharedMesh.triangles }).ToArray();cases.Add(new{hero=h,tier=tier,wing=wing,parts=parts});UnityEngine.Object.Destroy(host);UnityEngine.Object.Flush();}System.IO.File.WriteAllText("GEOMETRY_PATH",JsonSerializer.Serialize(cases));}}
'''.replace('GEOMETRY_PATH',str(output/'geometry.json')))
